import{_ as o,o as i,c as r,ah as n}from"./chunks/framework.5RDmLyoT.js";const a="/projects/Qtruck/en/latest/assets/image1.BQVYRPIs.webp",s="/projects/Qtruck/en/latest/assets/image2.COxhYUcb.webp",e="/projects/Qtruck/en/latest/assets/image3.uKNyT1e0.webp",l="/projects/Qtruck/en/latest/assets/image4.C8DJKzCc.webp",d="/projects/Qtruck/en/latest/assets/image1.BfhMpR4S.webp",c="/projects/Qtruck/en/latest/assets/image3.DTX07U4o.webp",A="/projects/Qtruck/en/latest/assets/image2.dUcm9wMN.webp",h="/projects/Qtruck/en/latest/assets/image4.DuStpIM-.webp",p="data:image/png;base64,",m="/projects/Qtruck/en/latest/assets/image6.ChtD3xtQ.webp",g="data:image/png;base64,",u="/projects/Qtruck/en/latest/assets/image8.tcPKb56D.webp",f="data:image/png;base64,",y="/projects/Qtruck/en/latest/assets/image10.ClR0ZJ8t.webp",b="/projects/Qtruck/en/latest/assets/image11.7I3V4f_4.webp",w="/projects/Qtruck/en/latest/assets/image12.CZVGq4Lc.webp",v="/projects/Qtruck/en/latest/assets/image13.DGzbcwTi.webp",j="/projects/Qtruck/en/latest/assets/image14.Bdvb5-IB.webp",x="/projects/Qtruck/en/latest/assets/image15.Btq1KQl4.webp",R="/projects/Qtruck/en/latest/assets/image16.D9uVMTEP.webp",B="/projects/Qtruck/en/latest/assets/image17.rZ9rNSOw.webp",E="data:image/png;base64,",k="data:image/png;base64,",C="/projects/Qtruck/en/latest/assets/image20.Xxe9LUQp.webp",O="/projects/Qtruck/en/latest/assets/image21.BE5CIZvw.webp",D="data:image/jpeg;base64,",P="/projects/Qtruck/en/latest/assets/image23.qZy3MYfl.webp",Q="/projects/Qtruck/en/latest/assets/image24.CzQeA2aW.webp",Z="/projects/Qtruck/en/latest/assets/image25.BfBaCDGK.webp",z="/projects/Qtruck/en/latest/assets/image26.C5EwEykF.webp",G=JSON.parse('{"title":"4. Remote Control Lesson","description":"","frontmatter":{},"headers":[],"relativePath":"docs/4.Remote_Control_Lesson.md","filePath":"docs/4.Remote_Control_Lesson.md"}'),I={name:"docs/4.Remote_Control_Lesson.md"};function X(U,t,W,H,q,F){return i(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="_4-remote-control-lesson" tabindex="-1">4. Remote Control Lesson <a class="header-anchor" href="#_4-remote-control-lesson" aria-label="Permalink to &quot;4. Remote Control Lesson&quot;">​</a></h1><h2 id="_4-1-quick-program-download-method" tabindex="-1">4.1 Quick Program Download Method <a class="header-anchor" href="#_4-1-quick-program-download-method" aria-label="Permalink to &quot;4.1 Quick Program Download Method&quot;">​</a></h2><p>(1) In this folder, find the <a href="../_static/source_code/Bluetooth_Control_program.zip">Qtruck-Bluetooth Control.hex</a> program file. Right-click on it or press <code>Ctrl+C</code> to copy the program.</p><img loading="lazy" height="94" width="739" src="'+a+'" class="common_img"><p>(2) After copying, paste it into the micro:bit drive.</p><img loading="lazy" height="143" width="838" src="'+s+'" class="common_img"><p>(3) The copy action is the download process. Once the download is complete, the hex file will disappear from the drive, and the drive will automatically eject.</p><p>You can also observe the yellow indicator light near the USB port on the micro:bit controller. During downloading, the light will flash rapidly.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>When the download is complete, it will stop flashing and stay on steadily.</p></div><p>After the download is complete, the hex file will disappear from the micro:bit drive. Once powered, the program will run automatically.</p><img loading="lazy" height="1258" src="'+e+'" class="common_img" width="400px"><p>Indicator light status after download (left) and successful program download confirmation (right)</p><img loading="lazy" height="123" width="508" src="'+l+'" class="common_img"><p>No hex file visible in the drive after download is complete</p><h2 id="_4-2-app-control" tabindex="-1">4.2 APP Control <a class="header-anchor" href="#_4-2-app-control" aria-label="Permalink to &quot;4.2 APP Control&quot;">​</a></h2><h3 id="_4-2-1-introduction-to-microbit-v2-0" tabindex="-1">4.2.1 Introduction to microbit V2.0 <a class="header-anchor" href="#_4-2-1-introduction-to-microbit-v2-0" aria-label="Permalink to &quot;4.2.1 Introduction to microbit V2.0&quot;">​</a></h3><p>Based on the original function of micro:bit V1.5, the new generation of micro:bit V2.0 has been optimized and improved in computing power and performance, as well as add several onboard modules for expansion.</p><p>All functions of micro:bit V1.5 can be implemented in micro:bit V2. Therefore, the tutorial for micro:bit V1.5 is applicable to micro:bit V2.0.</p><p>Regarding the new features of micro:bit V2.0, please see the related lessons.</p><p>The following table shows the comparison between two boards and the red parts highlights the new function of micro:bit V2.0.</p><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>micro:bit V1.5 vs V2 Comparison</title></head><body><table><caption>micro:bit V1.5 vs V2 Comparison</caption><thead><tr><th>No.</th><th>Feature</th><th>micro:bit V1.5</th><th>micro:bit V2</th></tr></thead><tbody><tr><td>1</td><td>Appearance</td><td><div class="image-container"><div class="image-pair"><img loading="lazy" height="316" width="391" src="'+d+'" style="width:300px;"><div class="image-label">Front</div></div><div class="image-pair"><img loading="lazy" height="321" width="387" src="'+c+'" style="width:300px;"><div class="image-label">Back</div></div></div></td><td><div class="image-container"><div class="image-pair"><img loading="lazy" height="325" width="393" src="'+A+'" style="width:300px;"><div class="image-label">Front</div></div><div class="image-pair"><img loading="lazy" height="321" width="389" src="'+h+'" style="width:300px;"><div class="image-label">Back</div></div></div></td></tr><tr><td>2</td><td>Processor</td><td>Nordic nRF51822</td><td>Nordic nRF52833</td></tr><tr><td>3</td><td>ARM</td><td>Cortex-M0 32bit 16MHz</td><td>Cortex-M4 32bit+FPU 64MHz</td></tr><tr><td>4</td><td>Memory/Flash</td><td>16KB RAM/256KB Flash</td><td>128KB RAM/512KB Flash</td></tr><tr><td>5</td><td>Touch Logo</td><td>None</td><td>Onboard touch sensor</td></tr><tr><td>6</td><td>Microphone</td><td>None</td><td>Onboard microphone with LED indicator</td></tr><tr><td>7</td><td>Speaker</td><td>None</td><td>Onboard electromagnetic speaker</td></tr><tr><td>8</td><td>Edge Connector</td><td>Flat type</td><td>Gear type</td></tr><tr><td>9</td><td>Reset Button</td><td>Reset function</td><td>Reset function, long press for power saving mode</td></tr><tr><td>10</td><td>Power Indicator</td><td>None</td><td>Red LED when powered</td></tr><tr><td>11</td><td>Bluetooth</td><td>Bluetooth 4.0</td><td>Bluetooth 5.0</td></tr><tr><td>12</td><td>Operating Current</td><td>90mA</td><td>300mA</td></tr></tbody></table></body></html><h3 id="_4-2-2-app-control" tabindex="-1">4.2.2 APP Control <a class="header-anchor" href="#_4-2-2-app-control" aria-label="Permalink to &quot;4.2.2 APP Control&quot;">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>This lesson takes iOS system as example and is also applicable to Android system.</p></div><p>iOS user can directly search and download <strong>&quot;Wonderbit&quot;</strong> in APP Store.</p><ul><li><strong>Program Download</strong></li></ul><p>(1) Please find <a href="../_static/source_code/Bluetooth_Control_program.zip">Qtruck-Bluetooth control.hex</a> program under folder <strong>&quot;APP Control Program&quot;</strong>.</p><img loading="lazy" height="44" width="380" src="'+p+'" class="common_img"><p>(2) Copy the program to micro:bit disk.</p><p>(3) After downloading, hex file is not visible in disk drive and the disk drive will automatically flash out. Also, you can see that the indicator next to USB port emits yellow light. The indicator will blink rapidly and continuously while your program is transferred and will stop flashing and keep on after transfer is complete.</p><img loading="lazy" height="1258" src="'+e+'" class="common_img" width="400px"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>After transfer is complete, hex file will disappear in micro:bit disk. After power on micro:bit, your program starts running on your micro:bit automatically.</p></div><img loading="lazy" height="149" width="782" src="'+m+'" class="common_img"><ul><li><strong>Install APP</strong></li></ul><p>Find and transfer <a href="https://play.google.com/store/apps/details?id=com.hiwonder.wonderbit" target="_blank" rel="noreferrer">Wonderbit.apk</a> installation package (only for Android user) to your phone. Download apk file on your phone and install app.</p><ul><li><strong>Connect to APP</strong></li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li>Before using app, please enable Bluetooth and GPS service in phone settings.</li><li>Click Bluetooth button on app to pair with robot. Do not connect robot by Bluetooth in your phone settings.</li></ul></div><p>(1) Enable Bluetooth and GPS service.</p><p>(2) Open Wonderbit. Click on <img loading="lazy" height="47" width="52" src="'+g+'" style="width:70px;"> to select <strong>&quot;Qtruck&quot;</strong>.</p><img loading="lazy" height="515" width="1083" src="'+u+'" class="common_img"><p>(3) Click on <img loading="lazy" height="46" width="45" src="'+f+'" style="width:70px;"> and select <strong>&quot;BBC micro:bit&quot;</strong> in pop-up device search list to connect.</p><img loading="lazy" height="478" width="1043" src="'+y+'" class="common_img"><img loading="lazy" height="506" width="1099" src="'+b+'" class="common_img"><p>(4) At the same time, keep your phone close to Qtruck. After connection is complete, Bluetooth icon on app will stop flashing and light up.</p><img loading="lazy" height="498" width="1090" src="'+w+'" class="common_img"><ul><li><strong>App Control</strong></li></ul><p>There are two functions on home interface of app including color light and servo control functions.</p><p>First of all, please learn about the color light function.</p><img loading="lazy" height="477" width="1055" src="'+v+'" class="common_img"><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Icon</strong></th><th style="text-align:center;"><strong>Function</strong></th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="181" width="199" src="'+j+'"></td><td style="text-align:center;">Control Qtruck to go forward or backward and turn left or right.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="102" width="166" src="'+x+'"></td><td style="text-align:center;">Display light intensity of environment where Qtruck is located.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="87" width="167" src="'+R+'"></td><td style="text-align:center;">Display the distance between Qtruck and object ahead.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="70" width="113" src="'+B+'"></td><td style="text-align:center;">Display temperature of environment where Qtruck is located.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="34" width="153" src="'+E+'"></td><td style="text-align:center;">Turn on this button, two color light on Qtruck emit random light (the light color is contained in surroundings).</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="26" width="133" src="'+k+'"></td><td style="text-align:center;">Turn on or off the color light.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="55" width="248" src="'+C+'"></td><td style="text-align:center;">Turn on Gravity control, you can tilt your phone to control Qtruck to move.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="199" width="224" src="'+O+'"></td><td style="text-align:center;">Control Qtruck&#39;s light color.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="145" width="162" src="'+D+'"></td><td style="text-align:center;">Click this button to open servo control interface.</td></tr></tbody></table><p>The home interface of servo control is as follow.</p><img loading="lazy" height="592" width="1296" src="'+P+'" class="common_img"><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Icon</strong></th><th style="text-align:center;"><strong>Function</strong></th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="78" width="198" src="'+Q+'"></td><td style="text-align:center;">Control <code>ID3</code> servo, i.e., gripper.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="86" width="211" src="'+Z+'"></td><td style="text-align:center;">Control <code>ID2</code> servo, i.e., the middle part of robotic arm.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="86" width="200" src="'+z+'"></td><td style="text-align:center;">Control <code>ID3</code> servo, i.e., the distal part of robotic arm.</td></tr></tbody></table>',52)])])}const K=o(I,[["render",X]]);export{G as __pageData,K as default};
